    42	  if (typeof element.type === "function") return resolveTree(await (element.type as (props: unknown) => ReactNode)(element.props));
    43	  const children = await resolveTree(element.props.children);
    44	  return cloneElement(element, {}, ...(Array.isArray(children) ? React.Children.toArray(children) : [children]));
